import json, random, subprocess, sys, os
sys.path.insert(0, '/workspace')
sys.path.insert(0, '/workspace/dev')
import ref

CLASSES = os.environ.get('CLASSES', '/workspace/tmp/classes')

def venc_w(v, w):
    assert v < 2**(8*w-2)
    return (([1,2,4,8].index(w) << (8*w-2)) | v).to_bytes(w, 'big')

def rv(rng, maxv=2**30):
    v = rng.randrange(0, maxv+1)
    ws = [w for w in (1,2,4,8) if v < 2**(8*w-2)]
    return venc_w(v, rng.choice(ws))

def rand_frame(rng):
    k = rng.randrange(0, 24)
    if k == 0: return b'\x00' * rng.randrange(1, 5)
    if k == 1: return b'\x01'
    if k in (2, 3):
        t = rng.choice([2, 3])
        la = rng.randrange(0, 30)
        first = rng.randrange(0, la+1)
        count = rng.randrange(0, 4)
        out = bytes([t]) + rv(rng, la) + rv(rng) + rv(rng, count) + rv(rng, first)
        low = la - first
        for _ in range(count):
            ok = rng.random() < 0.85
            if ok and low >= 2:
                gap = rng.randrange(0, low-1)
                high = low - gap - 2
                rg = rng.randrange(0, high+1)
            else:
                gap = rng.randrange(0, 40); rg = rng.randrange(0, 40)
            out += rv(rng, gap) + rv(rng, rg)
            low = low - gap - 2
        if t == 3:
            out += rv(rng) + rv(rng) + rv(rng)
        return out
    if k == 4: return b'\x04' + rv(rng) + rv(rng) + rv(rng)
    if k == 5: return b'\x05' + rv(rng) + rv(rng)
    if k == 6:
        data = bytes(rng.randrange(256) for _ in range(rng.randrange(0, 6)))
        return b'\x06' + rv(rng, 20) + rv(rng, 6) + data
    if k == 7: return b'\x07' + rv(rng)
    if k == 8:
        t = rng.randrange(8, 16)
        idv = rng.choice([0,1,2,3,4,5,6,7,8,11,15,16,20,100])
        out = bytes([t]) + rv(rng, idv)
        if t & 4: out += rv(rng, 20)
        data = bytes(rng.randrange(256) for _ in range(rng.randrange(0, 5)))
        if t & 2: out += rv(rng, len(data))
        return out + data
    if k == 9: return b'\x10' + rv(rng)
    if k == 10: return b'\x11' + rv(rng) + rv(rng)
    if k == 11:
        t = rng.choice([0x12, 0x13])
        v = rng.choice([rng.randrange(0, 2**60), rng.randrange(0, 2**60+3), 2**60])
        return bytes([t]) + rv(rng, min(v, 2**30))
    if k == 12: return b'\x14' + rv(rng)
    if k == 13: return b'\x15' + rv(rng) + rv(rng)
    if k == 14:
        t = rng.choice([0x16, 0x17])
        return bytes([t]) + rv(rng)
    if k == 15:
        seq = rng.randrange(0, 6)
        rpt = rng.randrange(0, 6)
        cidlen = rng.choice([1, 2, 3, 0, 21, 20])
        cid = bytes(rng.randrange(256) for _ in range(cidlen if 0 < cidlen <= 20 else 2))
        token = bytes(rng.randrange(256) for _ in range(16))
        return b'\x18' + rv(rng, seq) + rv(rng, rpt) + bytes([cidlen]) + cid + token
    if k == 16: return b'\x19' + rv(rng, 5)
    if k in (17, 18): return bytes([0x1a if k == 17 else 0x1b]) + bytes(rng.randrange(256) for _ in range(8))
    if k == 19:
        reason = bytes(rng.randrange(256) for _ in range(rng.randrange(0, 4)))
        return b'\x1c' + rv(rng) + rv(rng) + rv(rng, 3) + reason
    if k == 20:
        reason = bytes(rng.randrange(256) for _ in range(rng.randrange(0, 4)))
        return b'\x1d' + rv(rng) + rv(rng, 3) + reason
    if k == 21: return bytes([rng.choice([0x1e, 0x07])]) + rv(rng)
    if k == 22:
        if rng.random() < 0.5:
            return b'\x30' + bytes(rng.randrange(256) for _ in range(rng.randrange(0, 4)))
        data = bytes(rng.randrange(256) for _ in range(rng.randrange(0, 4)))
        return b'\x31' + rv(rng, 3) + data
    return bytes(rng.randrange(256) for _ in range(rng.randrange(1, 5)))

def rand_payload(rng):
    if rng.random() < 0.1:
        return bytes(rng.randrange(256) for _ in range(rng.randrange(0, 6)))
    out = b''
    for _ in range(rng.randrange(1, 5)):
        out += rand_frame(rng)
    return out

def rand_envelope(rng, local_width):
    level = rng.choice(['I','H','A'])
    pn = rng.randrange(0, 30)
    w = rng.choice([1,1,1,2,3,4])
    body = rand_payload(rng)
    if level == 'A':
        cid = bytes([rng.choice([0xaa, 0xbb, 0xcc])])
        phase = rng.randrange(2)
        spin = rng.randrange(2)
        first = 0x40 | (spin << 5) | (phase << 2) | (w-1)
        num = (pn % 2**(8*w)).to_bytes(w, 'big')
        return bytes([first]) + cid + num + body
    cid = bytes([rng.choice([0xaa, 0xbb])])
    scid = bytes([rng.choice([0x01, 0x02])])
    first = (0xc0 if level == 'I' else 0xe0) | (w-1)
    out = bytes([first]) + b'\x00\x00\x00\x01' + bytes([len(cid)]) + cid + bytes([len(scid)]) + scid
    if level == 'I':
        tok = bytes(rng.randrange(256) for _ in range(rng.randrange(0, 3)))
        out += venc_w(len(tok), rng.choice([1,2])) + tok
    num = (pn % 2**(8*w)).to_bytes(w, 'big')
    out += venc_w(w + len(body), rng.choice([1,2])) + num + body
    return out

def rand_wire(rng):
    r = rng.random()
    if r < 0.12:
        return bytes(rng.randrange(256) for _ in range(rng.randrange(0, 8)))
    if r < 0.2:
        return b''
    out = b''
    for _ in range(rng.randrange(1, 4)):
        if rng.random() < 0.12:
            out += bytes([rng.choice([0x80, 0xc4, 0xff, 0x00, 0x3f, 0x40, 0xc0, 0x90])]) \
                   + bytes(rng.randrange(256) for _ in range(rng.randrange(0, 6)))
            return out
        out += rand_envelope(rng, 1)
    return out

def rand_trace(rng):
    n_local = rng.randrange(1, 4)
    cids = []
    while len(cids) < n_local:
        c = bytes(rng.randrange(256) for _ in range(1))
        if c not in cids: cids.append(c)
    lim = dict(connection=rng.choice([0,1,5,10,2**62-1]), stream=rng.choice([0,1,3,8,2**62-1]),
               bidi=rng.choice([0,1,2,4,2**60]), uni=rng.choice([0,1,2,2**60]),
               cids=rng.randrange(2, 6))
    local = dict(bidi=rng.randrange(0, 3), uni=rng.randrange(0, 3), cids=[c.hex() for c in cids])
    peer = dict(cid='cc', token='00'*16)
    rec = dict(I=None, H=None, A=None)
    if rng.random() < 0.2:
        rec[rng.choice('IHA')] = rng.randrange(0, 5)
    events = []
    for _ in range(rng.randrange(0, 8)):
        if rng.random() < 0.25:
            ks = [k for k in ('I','H','A') if rng.random() < 0.5]
            events.append(dict(keys=ks))
        else:
            auth = [None if rng.random() < 0.3 else rng.randrange(0, 4)
                    for _ in range(rng.randrange(0, 5))]
            events.append(dict(datagram=dict(wire=rand_wire(rng).hex(), auth=auth)))
    return dict(limits=lim, local=local, peer=peer, received=rec, events=events)

def java_batch(traces):
    inp = json.dumps({"traces": traces})
    p = subprocess.run(['python3','/workspace/run.py',CLASSES], input=inp.encode(),
                       capture_output=True)
    if p.returncode != 0:
        raise RuntimeError(p.stderr.decode()[:3000])
    return json.loads(p.stdout)

def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 50
    rng = random.Random(seed)
    for it in range(rounds):
        traces = [rand_trace(rng) for _ in range(4)]
        got = java_batch(traces)['traces']
        exp = [ref.audit(t) for t in traces]
        for i, (g, e) in enumerate(zip(got, exp)):
            if json.dumps(g, sort_keys=True) != json.dumps(e, sort_keys=True):
                print("MISMATCH seed", seed, "iter", it, "trace", i)
                print("INPUT:", json.dumps(traces[i]))
                print("GOT:", json.dumps(g, sort_keys=True))
                print("EXP:", json.dumps(e, sort_keys=True))
                raise SystemExit(1)
        if it % 10 == 0:
            print("iter", it, "ok", flush=True)
    print("ALL OK", seed)

if __name__ == '__main__':
    main()
